import { Link } from 'react-router';
import { SewingButton, Ticket } from './art/objects';
import { Sticker } from './art/Sticker';
import '../styles/error.css';

interface ErrorBandProps {
  testId: string;
  title: string;
  message: string;
  actionLabel: string;
}

/** Full-viewport error band: a big sentence, two tumbling stickers and a plate-stack recovery action. */
export default function ErrorBand({ testId, title, message, actionLabel }: ErrorBandProps) {
  return (
    <section className="ft-band ft-area--error error-band empty-state" data-testid={testId} aria-labelledby="error-heading">
      <div className="ft-sticker-layer" aria-hidden="true">
        <Sticker object={Ticket} rotate={-48} className="ft-sticker ft-sticker--lg error-sticker error-sticker--ticket" />
        <Sticker object={SewingButton} rotate={36} className="ft-sticker ft-sticker--lg error-sticker error-sticker--button" />
      </div>
      <div className="ft-band__inner error-inner">
        <h1 id="error-heading" className="error-title">
          {title}
        </h1>
        <p className="error-message">{message}</p>
        <span className="ft-plates">
          <span className="ft-plate ft-plate--b" aria-hidden="true" />
          <span className="ft-plate ft-plate--a" aria-hidden="true" />
          <Link to="/" className="ft-btn ft-btn--primary">
            {actionLabel}
          </Link>
        </span>
      </div>
    </section>
  );
}
EOF
