cat > src/styles/error.css <<'EOF'
/* Full-viewport error band (404, unknown product). */
.error-band {
  flex: 1;
  display: flex;
  align-items: center;
  min-height: calc(100vh - 80px);
  overflow: hidden;
}

.error-inner {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.error-title {
  margin: 0;
  font-size: var(--font-size-display);
  line-height: var(--font-line-height-display);
  font-weight: var(--font-weight-medium);
  letter-spacing: var(--font-tracking-display);
}

.error-message {
  max-width: 720px;
  margin: var(--space-6) 0 var(--space-12);
  font-size: var(--font-size-lead);
  line-height: var(--font-line-height-lead);
}

.error-sticker--ticket {
  left: -2%;
  top: 8%;
}

.error-sticker--button {
  right: -2%;
  bottom: 6%;
}

@media (max-width: 1023px) {
  .error-band {
    min-height: calc(100vh - 64px);
  }
}

@media (max-width: 767px) {
  .error-band {
    padding-block: calc(var(--size-sticker-band) + var(--space-8));
  }

  .error-title {
    font-size: var(--font-size-display-mobile);
  }

  .error-message {
    font-size: var(--font-size-card-title);
    margin: var(--space-4) 0 var(--space-8);
  }

  .error-band .ft-sticker--lg {
    width: var(--size-sticker-band);
  }

  .error-sticker--ticket {
    left: -8%;
    top: 2%;
  }

  .error-sticker--button {
    right: -8%;
    bottom: 2%;
  }
}
EOF

